    fails += check(&.{ 0xF6, 0xF1 }, .@"div", .{ gp.r16(.rax), gp.r8(.rcx) }, .{  }, "F6F1 div(ax, cl)");
    fails += check(&.{ 0xF6, 0xF5 }, .@"div", .{ gp.r16(.rax), gp.r8hi(.rcx) }, .{  }, "F6F5 div(ax, ch)");
    try std.testing.expectEqual(@as(u32, 0), fails);
}

