    if (!opts.x86_64) return error.SkipZigTest;
    @setEvalBranchQuota(1_000_000);
    var fails: u32 = 0;
    fails += check(&.{ 0xF6, 0xB4, 0x11, 0x80, 0x00, 0x00, 0x00 }, .@"div", .{ gp.r16(.rax), gp.mem(x.Mem{ .base = .rcx, .index = .rdx, .scale = .x1, .disp = 128 }) }, .{  }, "F6B41180000000 div(ax, ptr(ecx, edx, 0, 128))");
