test "AsmJit x86 assembler tests (800..1200)" {
    if (!opts.x86_64) return error.SkipZigTest;
    @setEvalBranchQuota(1_000_000);
    var fails: u32 = 0;
    fails += check(&.{ 0x1A, 0xAC, 0x1A, 0x80, 0x00, 0x00, 0x00 }, .@"sbb", .{ gp.r8hi(.rcx), gp.mem(x.Mem{ .base = .rdx, .index = .rbx, .scale = .x1, .disp = 128 }) }, .{  }, "1AAC1A80000000 sbb(ch, ptr(edx, ebx, 0, 128))");
    fails += check(&.{ 0x1A, 0xAC, 0x1A, 0x80, 0x00, 0x00, 0x00 }, .@"sbb", .{ gp.r8hi(.rcx), gp.byte(x.Mem{ .base = .rdx, .index = .rbx, .scale = .x1, .disp = 128 }) }, .{  }, "1AAC1A80000000 sbb(ch, byte_ptr(edx, ebx, 0, 128))");
    fails += check(&.{ 0x66, 0x1B, 0x8C, 0x1A, 0x80, 0x00, 0x00, 0x00 }, .@"sbb", .{ gp.r16(.rcx), gp.mem(x.Mem{ .base = .rdx, .index = .rbx, .scale = .x1, .disp = 128 }) }, .{  }, "661B8C1A80000000 sbb(cx, ptr(edx, ebx, 0, 128))");
    fails += check(&.{ 0x66, 0x1B, 0x8C, 0x1A, 0x80, 0x00, 0x00, 0x00 }, .@"sbb", .{ gp.r16(.rcx), gp.word(x.Mem{ .base = .rdx, .index = .rbx, .scale = .x1, .disp = 128 }) }, .{  }, "661B8C1A80000000 sbb(cx, word_ptr(edx, ebx, 0, 128))");
    fails += check(&.{ 0x1B, 0x8C, 0x1A, 0x80, 0x00, 0x00, 0x00 }, .@"sbb", .{ gp.r32(.rcx), gp.mem(x.Mem{ .base = .rdx, .index = .rbx, .scale = .x1, .disp = 128 }) }, .{  }, "1B8C1A80000000 sbb(ecx, ptr(edx, ebx, 0, 128))");
    fails += check(&.{ 0x1B, 0x8C, 0x1A, 0x80, 0x00, 0x00, 0x00 }, .@"sbb", .{ gp.r32(.rcx), gp.dword(x.Mem{ .base = .rdx, .index = .rbx, .scale = .x1, .disp = 128 }) }, .{  }, "1B8C1A80000000 sbb(ecx, dword_ptr(edx, ebx, 0, 128))");
    fails += checkV(&.{ 0xAE }, .@"scas", .{ gp.r8(.rax), vec.Mem{ .base = .rdi, .scale = .x1, .disp = 0, .size = 0, .bcst = 0 } }, .{  }, "AE scas(al, ptr(edi))");
    fails += checkV(&.{ 0xAE }, .@"scas", .{ gp.r8(.rax), vec.Mem{ .base = .rdi, .scale = .x1, .disp = 0, .size = 1, .bcst = 0 } }, .{  }, "AE scas(al, byte_ptr(edi))");
