test "AsmJit x86 assembler tests (1600..2000)" {
    if (!opts.x86_64) return error.SkipZigTest;
    @setEvalBranchQuota(1_000_000);
    var fails: u32 = 0;
    fails += checkV(&.{ 0x66, 0x0F, 0x3A, 0x21, 0x8C, 0x1A, 0x80, 0x00, 0x00, 0x00, 0x01 }, .@"insertps", .{ vec.xmm(1), vec.Mem{ .base = .rdx, .index = .rbx, .scale = .x1, .disp = 128, .size = 4, .bcst = 0 }, 1 }, .{  }, "660F3A218C1A8000000001 insertps(xmm1, dword_ptr(edx, ebx, 0, 128), 1)");
