test "AsmJit x86 assembler tests (2000..2400)" {
    if (!opts.x86_64) return error.SkipZigTest;
    @setEvalBranchQuota(1_000_000);
    var fails: u32 = 0;
    fails += checkV(&.{ 0x0F, 0x0F, 0x8C, 0x1A, 0x80, 0x00, 0x00, 0x00, 0x86 }, .@"pfrcpv", .{ vec.mm(1), vec.Mem{ .base = .rdx, .index = .rbx, .scale = .x1, .disp = 128, .size = 0, .bcst = 0 } }, .{  }, "0F0F8C1A8000000086 pfrcpv(mm1, ptr(edx, ebx, 0, 128))");
    fails += checkV(&.{ 0x0F, 0x0F, 0x8C, 0x1A, 0x80, 0x00, 0x00, 0x00, 0x86 }, .@"pfrcpv", .{ vec.mm(1), vec.Mem{ .base = .rdx, .index = .rbx, .scale = .x1, .disp = 128, .size = 8, .bcst = 0 } }, .{  }, "0F0F8C1A8000000086 pfrcpv(mm1, qword_ptr(edx, ebx, 0, 128))");
    fails += checkV(&.{ 0x0F, 0x0F, 0xCA, 0xA7 }, .@"pfrsqit1", .{ vec.mm(1), vec.mm(2) }, .{  }, "0F0FCAA7 pfrsqit1(mm1, mm2)");
    fails += checkVS(&.{ 0x0F, 0x0F, 0x8C, 0x1A, 0x80, 0x00, 0x00, 0x00, 0xA7 }, .@"pfrsqit1", .{ vec.mm(1), vec.Mem{ .base = .rdx, .index = .rbx, .scale = .x1, .disp = 128, .size = 0, .bcst = 0 } }, .{  }, "0F0F8C1A80000000A7 pfrsqit1(mm1, ptr(edx, ebx, 0, 128))");
