test "AsmJit x86 assembler tests (2400..2800)" {
    if (!opts.x86_64) return error.SkipZigTest;
    @setEvalBranchQuota(1_000_000);
    var fails: u32 = 0;
    fails += checkV(&.{ 0x0F, 0x60, 0xCA }, .@"punpcklbw", .{ vec.mm(1), vec.mm(2) }, .{  }, "0F60CA punpcklbw(mm1, mm2)");
    fails += checkV(&.{ 0x0F, 0x60, 0x8C, 0x1A, 0x80, 0x00, 0x00, 0x00 }, .@"punpcklbw", .{ vec.mm(1), vec.Mem{ .base = .rdx, .index = .rbx, .scale = .x1, .disp = 128, .size = 0, .bcst = 0 } }, .{  }, "0F608C1A80000000 punpcklbw(mm1, ptr(edx, ebx, 0, 128))");
