test "AsmJit x86 assembler tests (4000..4400)" {
    if (!opts.x86_64) return error.SkipZigTest;
    @setEvalBranchQuota(1_000_000);
    var fails: u32 = 0;
    fails += checkV(&.{ 0xC4, 0xE2, 0x79, 0x0E, 0xCA }, .@"vtestps", .{ vec.xmm(1), vec.xmm(2) }, .{  }, "C4E2790ECA vtestps(xmm1, xmm2)");
    fails += checkV(&.{ 0xC4, 0xE2, 0x79, 0x0E, 0x8C, 0x1A, 0x80, 0x00, 0x00, 0x00 }, .@"vtestps", .{ vec.xmm(1), vec.Mem{ .base = .rdx, .index = .rbx, .scale = .x1, .disp = 128, .size = 0, .bcst = 0 } }, .{  }, "C4E2790E8C1A80000000 vtestps(xmm1, ptr(edx, ebx, 0, 128))");
    fails += checkV(&.{ 0xC4, 0xE2, 0x79, 0x0E, 0x8C, 0x1A, 0x80, 0x00, 0x00, 0x00 }, .@"vtestps", .{ vec.xmm(1), vec.Mem{ .base = .rdx, .index = .rbx, .scale = .x1, .disp = 128, .size = 16, .bcst = 0 } }, .{  }, "C4E2790E8C1A80000000 vtestps(xmm1, xmmword_ptr(edx, ebx, 0, 128))");
