test "AsmJit x86 assembler tests (6000..6400)" {
    if (!opts.x86_64) return error.SkipZigTest;
    @setEvalBranchQuota(1_000_000);
    var fails: u32 = 0;
    fails += checkV(&.{ 0x62, 0xF1, 0x6D, 0x28, 0x75, 0x4C, 0x2B, 0x04 }, .@"vpcmpeqw", .{ vec.k(1), vec.ymm(2), vec.Mem{ .base = .rbx, .index = .rbp, .scale = .x1, .disp = 128, .size = 32, .bcst = 0 } }, .{  }, "62F16D28754C2B04 vpcmpeqw(k1, ymm2, ymmword_ptr(ebx, ebp, 0, 128))");
