test "AsmJit x86 assembler tests (7200..7600)" {
    if (!opts.x86_64) return error.SkipZigTest;
    @setEvalBranchQuota(1_000_000);
    var fails: u32 = 0;
    fails += checkV(&.{ 0x62, 0xF1, 0x75, 0x48, 0x71, 0x54, 0x1A, 0x02, 0x01 }, .@"vpsrlw", .{ vec.zmm(1), vec.Mem{ .base = .rdx, .index = .rbx, .scale = .x1, .disp = 128, .size = 0, .bcst = 0 }, 1 }, .{  }, "62F1754871541A0201 vpsrlw(zmm1, ptr(edx, ebx, 0, 128), 1)");
