test "AsmJit x86 assembler tests (7600..8000)" {
    if (!opts.x86_64) return error.SkipZigTest;
    @setEvalBranchQuota(1_000_000);
    var fails: u32 = 0;
    fails += checkV(&.{ 0x62, 0xF3, 0x54, 0x48, 0xC2, 0xEC, 0x7B }, .@"vcmpph", .{ vec.k(5), vec.zmm(5), vec.zmm(4), 123 }, .{  }, "62F35448C2EC7B vcmpph(k5, zmm5, zmm4, 123)");
    fails += checkV(&.{ 0x62, 0xF3, 0x54, 0x18, 0xC2, 0xEC, 0x7B }, .@"vcmpph", .{ vec.k(5), vec.zmm(5), vec.zmm(4), 123 }, .{ .sae = true }, "62F35418C2EC7B vcmpph(k5, zmm5, zmm4, 123)");
    fails += checkV(&.{ 0x62, 0xF3, 0x54, 0x4F, 0xC2, 0xAC, 0xF4, 0x00, 0x00, 0x00, 0x10, 0x7B }, .@"vcmpph", .{ vec.k(5), vec.zmm(5), vec.Mem{ .base = .rsp, .index = .rsi, .scale = .x8, .disp = 268435456, .size = 64, .bcst = 0 }, 123 }, .{ .k = 7 }, "62F3544FC2ACF4000000107B vcmpph(k5, zmm5, zmmword_ptr(esp, esi, 3, 268435456), 123)");
    fails += checkVS(&.{ 0x62, 0xF3, 0x54, 0x58, 0xC2, 0x29, 0x7B }, .@"vcmpph", .{ vec.k(5), vec.zmm(5), vec.Mem{ .base = .rcx, .scale = .x1, .disp = 0, .size = 2, .bcst = 32 }, 123 }, .{  }, "62F35458C2297B vcmpph(k5, zmm5, word_ptr(ecx)._1to32(), 123)");
    fails += checkV(&.{ 0x62, 0xF3, 0x54, 0x48, 0xC2, 0x69, 0x7F, 0x7B }, .@"vcmpph", .{ vec.k(5), vec.zmm(5), vec.Mem{ .base = .rcx, .scale = .x1, .disp = 8128, .size = 64, .bcst = 0 }, 123 }, .{  }, "62F35448C2697F7B vcmpph(k5, zmm5, zmmword_ptr(ecx, 8128), 123)");
    fails += checkV(&.{ 0x62, 0xF3, 0x54, 0x5F, 0xC2, 0x6A, 0x80, 0x7B }, .@"vcmpph", .{ vec.k(5), vec.zmm(5), vec.Mem{ .base = .rdx, .scale = .x1, .disp = -256, .size = 2, .bcst = 32 }, 123 }, .{ .k = 7 }, "62F3545FC26A807B vcmpph(k5, zmm5, word_ptr(edx, -256)._1to32(), 123)");
